package com.weearntogether.play

import android.app.Activity
import android.os.Bundle
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.widget.*

class MainActivity : Activity() {
    private val navy=Color.rgb(7,12,31); private val panel=Color.rgb(18,27,58); private val purple=Color.rgb(105,70,230); private val blue=Color.rgb(32,116,232); private val gold=Color.rgb(255,197,77)
    private lateinit var root:LinearLayout
    private val loyalty by lazy{LoyaltyProgress(this)}; private val playHistory by lazy{PlayHistory(this)}; private val profile by lazy{getSharedPreferences("wet_guest_profile",MODE_PRIVATE)}
    private var levelPlay:LevelPlayManager?=null
    private fun tr(s:String)=AppLocale.t(s)
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(profile.contains("guest_id")){initAds();home()}else welcome()}
    private fun initAds(){if(levelPlay!=null)return;val id=profile.getString("guest_id",null)?:return;levelPlay=LevelPlayManager(this,id);levelPlay?.initialize()}
    private fun rounded(color:Int,r:Float)=GradientDrawable().apply{setColor(color);cornerRadius=r}
    private fun gradient()=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(purple,blue)).apply{cornerRadius=30f}
    private fun layout(title:String){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(22,32,22,34);setBackgroundColor(navy)};setContentView(ScrollView(this).apply{isFillViewport=true;addView(root)});if(title.isNotEmpty())text(title,30)}
    private fun text(s:String,size:Int=17,color:Int=Color.WHITE){root.addView(TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);setPadding(4,10,4,10);if(size>=23)setTypeface(null,Typeface.BOLD)})}
    private fun button(label:String,action:()->Unit){root.addView(Button(this).apply{text=label;textSize=16f;isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);background=gradient();setPadding(18,12,18,12);minHeight=0;minimumHeight=0;setOnClickListener{action()}},LinearLayout.LayoutParams(-1,120).apply{bottomMargin=14})}
    private fun gameCard(title:String,subtitle:String,badge:String,action:()->Unit){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,24,28,26);background=rounded(panel,34f);isClickable=true;isFocusable=true;setOnClickListener{action()}};box.addView(TextView(this).apply{text=badge;textSize=13f;setTextColor(gold);setTypeface(null,Typeface.BOLD)});box.addView(TextView(this).apply{text=title;textSize=24f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);setPadding(0,9,0,8);maxLines=1});box.addView(TextView(this).apply{text=tr(subtitle);textSize=14f;setTextColor(0xffbdc8e7.toInt());maxLines=2});root.addView(box,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=16})}
    private fun welcome(){layout(tr("Mirë se vjen"));text("WE EARN TOGETHER",15,gold);text(tr("Luaj. Përparoi. Zhblloko sfida."),24);text(tr("Krijo profilin lokal për të ruajtur progresin."),16,Color.LTGRAY);val e=EditText(this).apply{hint=tr("Emri në lojë");setSingleLine(true);setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);setPadding(28,20,28,20);background=rounded(panel,28f)};root.addView(e,LinearLayout.LayoutParams(-1,120).apply{bottomMargin=22});button(tr("VAZHDO")){val n=e.text.toString().trim().ifBlank{tr("Lojtar")};profile.edit().putString("display_name",n).putString("guest_id",java.util.UUID.randomUUID().toString()).putLong("created_at",System.currentTimeMillis()).apply();initAds();home()}}
    private fun markAndOpen(game:String,open:()->Unit){playHistory.mark(game);open()}
    private fun resumeLast(){when(playHistory.lastGame){"bubble"->bubbleShooter();"block"->blockPuzzle();"stack"->neonStack();"lines"->colorLines();"2048"->merge2048();else->gamesHub()}}
    private fun nav(){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;setPadding(0,10,0,8);background=rounded(0xff0e1834.toInt(),28f)};fun item(label:String,action:()->Unit){row.addView(Button(this).apply{text=label;isAllCaps=false;textSize=12f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);minHeight=0;minimumHeight=0;background=rounded(panel,18f);setOnClickListener{action()}},LinearLayout.LayoutParams(0,104,1f).apply{setMargins(4,4,4,4)})};item("Home"){home()};item("Games"){gamesHub()};item("Progress"){progressDashboard()};item("Profile"){account()};root.addView(row,LinearLayout.LayoutParams(-1,132).apply{topMargin=10})}
    private fun home(){layout("");val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};top.addView(TextView(this).apply{text="WE EARN TOGETHER";textSize=17f;setTextColor(gold);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,76,1f));top.addView(Button(this).apply{text=profile.getString("display_name",tr("Lojtar"));isAllCaps=false;setTextColor(Color.WHITE);minHeight=0;minimumHeight=0;background=rounded(panel,24f);setOnClickListener{account()}},LinearLayout.LayoutParams(230,76));root.addView(top);root.addView(PremiumHeroView(this),LinearLayout.LayoutParams(-1,360).apply{bottomMargin=20});val stats=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=rounded(panel,30f);setPadding(12,18,12,18)};fun stat(v:String,l:String,c:Int){stats.addView(TextView(this).apply{text="$v\n$l";gravity=Gravity.CENTER;textSize=16f;setTextColor(c);setTypeface(null,Typeface.BOLD);setPadding(4,8,4,8)},LinearLayout.LayoutParams(0,-2,1f))};stat(loyalty.points.toString(),tr("PIKË"),gold);stat(loyalty.currentStreak.toString(),"STREAK",Color.WHITE);stat("${loyalty.todayGames}/${loyalty.dailyGoal}",tr("SOT"),Color.WHITE);root.addView(stats,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=22});if(playHistory.lastGame!=null){text("CONTINUE PLAYING",14,gold);button("Continue"){resumeLast()}};text(tr("FEATURED"),15,gold);gameCard("BUBBLE SHOOTER","Gjuajtje e shpejtë • nivele • rekord","ARCADE"){markAndOpen("bubble"){bubbleShooter()}};gameCard("BLOCK PUZZLE","Strategji • kombinime • progres","PUZZLE"){markAndOpen("block"){blockPuzzle()}};gameCard("COLOR LINES","Strategy 9×9 • build lines of 5+ • high score","STRATEGY"){markAndOpen("lines"){colorLines()}};gameCard("NEON STACK","Precision timing • perfect drops • high score","ARCADE"){markAndOpen("stack"){neonStack()}};nav()}
    private fun gamesHub(){layout("GAMES");gameCard("BUBBLE SHOOTER","Gjuajtje e shpejtë • nivele • rekord","ARCADE"){markAndOpen("bubble"){bubbleShooter()}};gameCard("BLOCK PUZZLE","Strategji • kombinime • progres","PUZZLE"){markAndOpen("block"){blockPuzzle()}};gameCard("COLOR LINES","Strategy 9×9 • build lines of 5+ • high score","STRATEGY"){markAndOpen("lines"){colorLines()}};gameCard("NEON STACK","Precision timing • perfect drops • high score","ARCADE"){markAndOpen("stack"){neonStack()}};gameCard("2048","Bashko numrat dhe arrij rekordin","LOGIC"){markAndOpen("2048"){merge2048()}};nav()}
    private fun account(){layout(tr("Profili"));text(profile.getString("display_name",tr("Lojtar"))?:tr("Lojtar"),24,gold);val e=EditText(this).apply{setText(profile.getString("display_name",tr("Lojtar")));setTextColor(Color.WHITE);setSingleLine(true);background=rounded(panel,26f);setPadding(24,10,24,10)};root.addView(e,LinearLayout.LayoutParams(-1,110).apply{bottomMargin=16});button(tr("Ruaj emrin")){val n=e.text.toString().trim();if(n.isNotEmpty()){profile.edit().putString("display_name",n).apply();account()}};nav()}
    private fun progressDashboard(){layout(tr("Progresi"));text(tr("${loyalty.points} PIKË"),30,gold);text(tr("Lojëra: ${loyalty.gamesPlayed}   •   Streak: ${loyalty.currentStreak}   •   Rekord: ${loyalty.bestStreak}"),17);val done=loyalty.todayGames.coerceAtMost(loyalty.dailyGoal);text(tr("SFIDA DITORE"),16,gold);root.addView(ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=loyalty.dailyGoal;progress=done},LinearLayout.LayoutParams(-1,34).apply{bottomMargin=18});if(loyalty.dailyClaimed)text(tr("Bonusi ditor është marrë."),16,gold)else if(done>=loyalty.dailyGoal)button(tr("Merr 100 pikë")){loyalty.claimDailyChallenge();progressDashboard()};nav()}
    private fun bubbleShooter(){playHistory.mark("bubble");layout("Bubble Shooter");text(tr("Syno • gjuaj • pastro tabelën. Prek topin 'Tjetra' për ta ndërruar."),15,gold);val game=BubbleShooterView(this){levelPlay?.showInterstitialAtNaturalBreak()};root.addView(game,LinearLayout.LayoutParams(-1,1350));button(tr("Rifillo")){game.restart()};button("Play Hub"){home()}}
    private fun colorLines(){playHistory.mark("lines");layout("Color Lines");text("9×9 strategy • move balls • create lines of 5+",15,gold);val game=ColorLinesView(this);root.addView(game,LinearLayout.LayoutParams(-1,1450));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
    private fun neonStack(){playHistory.mark("stack");layout("Neon Stack");text("Precision timing • perfect drops • persistent best score",15,gold);val game=NeonStackView(this);root.addView(game,LinearLayout.LayoutParams(-1,1450));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
    private fun merge2048(){playHistory.mark("2048");layout("2048");val game=Merge2048View(this);root.addView(game,LinearLayout.LayoutParams(-1,1100));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
    private fun blockPuzzle(){playHistory.mark("block");layout("Block Puzzle");val game=BlockPuzzleView(this);root.addView(game,LinearLayout.LayoutParams(-1,1350));button(tr("Rifillo")){game.restart()};button("Play Hub"){levelPlay?.showInterstitialAtNaturalBreak();home()}}
}
